"use client";

import { Toggle as TogglePrimitive } from "@base-ui/react/toggle";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

const toggleVariants = cva(
  // Pressed is the era's recessed state: the gel fills in and the whole face
  // sinks under an inner shadow, the same trick the tab strip pulls.
  "group/toggle relative inline-flex shrink-0 select-none items-center justify-center gap-1.5 overflow-hidden whitespace-nowrap rounded-full font-semibold tracking-[-0.01em] outline-none focus-visible:outline-hidden transition-[filter,background,border-color,scale] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] before:pointer-events-none before:absolute before:inset-x-[4px] before:top-[1px] before:h-[46%] before:rounded-[9999px_9999px_8px_8px] before:bg-[image:var(--aqua-gel-shine,linear-gradient(180deg,rgba(255,255,255,0.92)_0%,rgba(255,255,255,0.5)_55%,rgba(255,255,255,0.24)_100%))] before:[mask-image:linear-gradient(90deg,transparent_0%,black_7px,black_calc(100%_-_7px),transparent_100%)] before:opacity-0 before:content-[''] active:scale-[0.97] hover:brightness-105 focus-visible:ring-[3px] focus-visible:ring-[var(--aqua-ring,#2f7de0)] active:brightness-95 disabled:pointer-events-none disabled:opacity-50 data-disabled:pointer-events-none data-disabled:opacity-50 data-pressed:border-[var(--aqua-gel-border,#42689e)] data-pressed:border-b-[var(--aqua-gel-border-bottom,#587497)] data-pressed:bg-[linear-gradient(180deg,var(--aqua-gel-top,#cadefa)_0%,var(--aqua-gel-upper,#a2c5f4)_46%,var(--aqua-gel-body,#5d98e8)_50%,var(--aqua-gel-lower,#89b5f0)_68%,var(--aqua-gel-top,#cadefa)_88%,var(--aqua-gel-glow,#dae8fc)_100%)] data-pressed:text-black dark:data-pressed:text-white dark:data-pressed:[text-shadow:0_-1px_1px_rgba(0,0,0,0.45)] data-pressed:shadow-[inset_0_1px_2px_var(--aqua-gel-rim,rgba(47,125,224,0.45)),inset_0_-2px_3px_var(--aqua-gel-inset-bottom,rgba(255,255,255,0.78)),inset_2px_0_4px_-1px_var(--aqua-gel-rim,rgba(47,125,224,0.45)),inset_-2px_0_4px_-1px_var(--aqua-gel-rim,rgba(47,125,224,0.45))] data-pressed:before:opacity-100 data-pressed:[text-shadow:0_1px_0_rgba(255,255,255,0.5)] [&_svg]:pointer-events-none [&_svg]:shrink-0 forced-colors:data-pressed:forced-color-adjust-none forced-colors:data-pressed:bg-none forced-colors:data-pressed:bg-[Highlight] forced-colors:data-pressed:text-[HighlightText]",
  {
    variants: {
      variant: {
        default:
          "border border-transparent bg-transparent text-[var(--aqua-text,#3a3f47)] [text-shadow:0_1px_0_rgba(255,255,255,0.8)] hover:border-[var(--aqua-border-light,#c3c7cf)] hover:bg-[image:var(--aqua-surface-metal)]",
        outline:
          "border border-[var(--aqua-border-strong,#8b909a)] bg-[image:var(--aqua-surface-metal)] text-[var(--aqua-text,#3a3f47)] shadow-[inset_0_1px_1px_rgba(255,255,255,0.9),0_1px_2px_rgba(20,60,130,0.2)] [text-shadow:0_1px_0_rgba(255,255,255,0.8)]",
      },
      size: {
        sm: "h-7 min-w-7 px-3 text-[12px] [&_svg:not([class*='size-'])]:size-3.5",
        default:
          "h-8 min-w-8 px-3.5 text-[13px] [&_svg:not([class*='size-'])]:size-4",
        lg: "h-9 min-w-9 px-4 text-[15px] [&_svg:not([class*='size-'])]:size-4",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

function Toggle({
  className,
  variant = "default",
  size = "default",
  ...props
}: TogglePrimitive.Props & VariantProps<typeof toggleVariants>) {
  return (
    <TogglePrimitive
      data-slot="toggle"
      className={cn(toggleVariants({ variant, size, className }))}
      {...props}
    />
  );
}

export { Toggle, toggleVariants };
